// Your watchlist of CIK numbers (SEC company identifiers)
// Find CIKs at: https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany
const watchlist = [
  { cik: '0000320193', name: 'Apple Inc.' },
  { cik: '0000789019', name: 'Microsoft Corp.' },
  { cik: '0001652044', name: 'Alphabet Inc.' },
  { cik: '0001018724', name: 'Amazon.com Inc.' },
  { cik: '0001045810', name: 'NVIDIA Corp.' }
];

return watchlist.map(company => ({ json: company }));

const data = $input.first().json.body;
const recentFilings = data.filings?.recent || {};

// Get filings from last 24 hours
const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

const importantForms = ['8-K', '10-K', '10-Q', '4', 'SC 13G', 'SC 13D', '13F-HR'];

const newFilings = [];
for (let i = 0; i < recentFilings.filingDate?.length; i++) {
  const filingDate = new Date(recentFilings.filingDate[i]);
  const form = recentFilings.form[i];

  if (filingDate > oneDayAgo && importantForms.includes(form)) {
    newFilings.push({
      form: form,
      filingDate: recentFilings.filingDate[i],
      accessionNumber: recentFilings.accessionNumber[i],
      primaryDocument: recentFilings.primaryDocument[i],
      description: recentFilings.primaryDocDescription?.[i] || '',
      company: data.name,
      cik: data.cik
    });
  }
}

return newFilings.map(f => ({ json: f }));

const filing = $input.first().json;

const formDescriptions = {
  '8-K': 'Material Event',
  '10-K': 'Annual Report',
  '10-Q': 'Quarterly Report',
  '4': 'Insider Transaction',
  'SC 13G': 'Passive Investment >5%',
  'SC 13D': 'Active Investment >5%',
  '13F-HR': 'Institutional Holdings'
};

const docUrl = `https://www.sec.gov/Archives/edgar/data/${filing.cik}/${filing.accessionNumber.replace(/-/g, '')}/${filing.primaryDocument}`;

const message = `🚨 *New SEC Filing*\n\n` +
  `*Company:* ${filing.company}\n` +
  `*Form:* ${filing.form} (${formDescriptions[filing.form] || 'Other'})\n` +
  `*Filed:* ${filing.filingDate}\n` +
  `*Description:* ${filing.description}\n\n` +
  `📄 [View Filing](${docUrl})`;

return [{ json: { message, url: docUrl } }];
